import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{w as t}from"./framer-5rYXpS6P.js";import{It as n,Xn as r,ir as i,t as a,wn as o}from"./icons-CE39CflY.js";import{n as s,t as c}from"./ArticleLayout-DZW47Eny.js";var l,u,d=e((()=>{a(),l=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Assurer un véhicule acheté chez un particulier : roulez dès le premier trajet`,description:`Vous achetez une voiture à un particulier ? Vous devez être assuré avant le premier kilomètre. Assurance temporaire AssuTempo : attestation en 5 minutes, sans attendre la carte grise.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurer-vehicule-achete-chez-particulier`,dateModified:`2026-06-03`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Assurer un véhicule acheté chez un particulier`,item:`https://assutempo.fr/articles/assurer-vehicule-achete-chez-particulier`}]},{"@context":`https://schema.org`,"@type":`HowTo`,name:`Comment s'assurer après l'achat d'un véhicule entre particuliers`,totalTime:`PT5M`,step:[{"@type":`HowToStep`,position:1,name:`Choisissez la durée (1 à 90 j)`,text:`Sélectionnez le nombre de jours dont vous avez besoin selon votre situation.`},{"@type":`HowToStep`,position:2,name:`Renseignez le véhicule (carte grise + cession)`,text:`Indiquez les informations du véhicule à partir de la carte grise du vendeur et du certificat de cession.`},{"@type":`HowToStep`,position:3,name:`Payez en ligne`,text:`Paiement sécurisé par carte bancaire, sans engagement.`},{"@type":`HowToStep`,position:4,name:`Recevez l'attestation (5 min)`,text:`Votre Mémo Véhicule Assuré et votre carte internationale d'assurance automobile arrivent par email.`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Dois-je attendre la carte grise pour m'assurer ?`,acceptedAnswer:{"@type":`Answer`,text:`Non. Vous vous assurez immédiatement, avec la carte grise du vendeur et le certificat de cession.`}},{"@type":`Question`,name:`Y a-t-il un délai pour s'assurer après l'achat ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, aucun délai de grâce : l'assurance est obligatoire dès le premier trajet.`}},{"@type":`Question`,name:`Combien de temps pour faire la carte grise ?`,acceptedAnswer:{"@type":`Answer`,text:`Un mois à partir de la date du certificat de cession.`}},{"@type":`Question`,name:`Quels documents pour souscrire l'assurance ?`,acceptedAnswer:{"@type":`Answer`,text:`Permis, carte grise du véhicule, certificat de cession, moyen de paiement.`}},{"@type":`Question`,name:`Reçois-je une carte verte ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, elle a été supprimée en avril 2024. Vous recevez un Mémo Véhicule Assuré et une carte internationale d'assurance automobile (valable dans 34 pays) ; le contrôle se fait à la plaque via le FVA.`}}]}],u={slug:`assurer-vehicule-achete-chez-particulier`,seo:{title:`Assurer un véhicule acheté chez un particulier : roulez dès le premier trajet`,description:`Vous achetez une voiture à un particulier ? Vous devez être assuré avant le premier kilomètre. Assurance temporaire AssuTempo : attestation en 5 minutes, sans attendre la carte grise.`,canonical:`https://assutempo.fr/articles/assurer-vehicule-achete-chez-particulier`,jsonLd:l},category:`Achat véhicule`,readTime:`5 min`,updatedDate:`3 juin 2026`,author:`Evidence Assurances`,headline:`Assurer un véhicule acheté chez un particulier`,immediateAnswer:`Quand vous achetez une voiture ou une moto à un particulier, vous devez être assuré avant le premier kilomètre : la loi ne prévoit aucun délai de grâce après la vente. L'assurance temporaire AssuTempo vous couvre immédiatement, sans attendre que la carte grise soit à votre nom.`,sections:[{type:`alert`,heading:`L'essentiel`,items:[`Assurance obligatoire dès le premier trajet : aucun délai de grâce après l'achat (art. L211-1 du Code des assurances).`,`Pas besoin d'attendre la carte grise à votre nom pour vous assurer.`,`1 mois pour faire la carte grise, à partir de la date du certificat de cession.`,`Attestation en 5 minutes, durée de 1 à 90 jours.`]},{type:`stepflow`,ariaLabel:`Comment s'assurer après un achat entre particuliers en 4 étapes : durée, véhicule, paiement, attestation`,steps:[{icon:i,label:`Choisissez la durée (1 à 90 j)`},{icon:r,label:`Renseignez le véhicule (carte grise + cession)`},{icon:o,label:`Payez en ligne`},{icon:n,label:`Recevez l'attestation (5 min)`}]},{type:`text`,heading:`Faut-il assurer la voiture avant de la ramener ?`,paragraphs:[`Oui, dès le premier mètre. Contrairement à une idée répandue, il n'existe aucun délai de grâce après l'achat : la responsabilité civile est obligatoire avant même le trajet de retour. Vous pouvez être couvert en quelques minutes avec une assurance temporaire, le temps de mettre en place votre contrat annuel.`]},{type:`text`,heading:`Peut-on s'assurer sans avoir la carte grise à son nom ?`,paragraphs:[`Oui. La souscription se fait à partir de la carte grise du vendeur et du certificat de cession ; inutile d'attendre que la carte grise soit à votre nom. C'est précisément le rôle de l'assurance temporaire : vous couvrir pendant la transition.`]},{type:`checklist`,heading:`Quels documents pour la carte grise ?`,intro:`Dans le mois suivant l'achat, réunissez :`,relatedLink:{text:`Rouler en attendant sa carte grise définitive`,href:`/articles/assurance-temporaire-rouler-en-attendant-carte-grise`},items:[`Le certificat d'immatriculation barré, daté et signé "vendu le…" par le vendeur`,`Le certificat de cession (Cerfa 15776)`,`Le code de cession remis par le vendeur après sa déclaration sur l'ANTS`,`Le certificat de situation administrative (non-gage) de moins d'un mois`,`Le contrôle technique de moins de 6 mois si le véhicule a plus de 4 ans`,`Un justificatif de domicile et une pièce d'identité`]},{type:`text`,heading:`Quels documents reçoit-on avec l'assurance ?`,paragraphs:[`Depuis avril 2024, la carte verte n'existe plus. En France, la preuve d'assurance se fait à la plaque, via le Fichier des Véhicules Assurés (FVA). Votre contrat comprend votre Mémo Véhicule Assuré (à conserver avec les papiers du véhicule) et votre carte internationale d'assurance automobile, valable dans les 34 pays couverts.`],relatedLink:{text:`Véhicule ou permis étranger : assurance temporaire en France`,href:`/articles/assurance-temporaire-vehicule-etranger-france`}},{type:`text`,heading:`Combien de temps souscrire ?`,paragraphs:[`De 1 à 90 jours, au jour près. La plupart des acheteurs couvrent le temps de faire la carte grise et de souscrire leur assurance annuelle. Sans engagement.`],relatedLink:{text:`Essayer un véhicule avant achat, bien assuré`,href:`/articles/assurance-temporaire-essai-vehicule-avant-achat`}},{type:`text`,heading:`Que risque-t-on en roulant sans assurance ?`,paragraphs:[`Rouler sans assurance est un délit : amende, et surtout prise en charge personnelle de tous les dommages en cas d'accident.`],relatedLink:{text:`Contrôlé sans assurance : risques, amende et que faire`,href:`/articles/controle-sans-assurance-risques-amende`}}],faqItems:[{q:`Dois-je attendre la carte grise pour m'assurer ?`,a:`Non. Vous vous assurez immédiatement, avec la carte grise du vendeur et le certificat de cession.`},{q:`Y a-t-il un délai pour s'assurer après l'achat ?`,a:`Non, aucun délai de grâce : l'assurance est obligatoire dès le premier trajet.`},{q:`Combien de temps pour faire la carte grise ?`,a:`Un mois à partir de la date du certificat de cession.`},{q:`Quels documents pour souscrire l'assurance ?`,a:`Permis, carte grise du véhicule, certificat de cession, moyen de paiement.`},{q:`Reçois-je une carte verte ?`,a:`Non, elle a été supprimée. Vous recevez un Mémo Véhicule Assuré et une carte internationale d'assurance (valable dans 34 pays) ; le contrôle se fait à la plaque via le FVA.`}]}}));function f(){return(0,p.jsx)(c,{data:u})}var p;e((()=>{s(),d(),p=t()}))();export{f as default};